// Generated by Apply-Nexora-Demo-Package-Screens.ps1
using System;
using System.Collections.Generic;
using System.Collections.ObjectModel;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using Nexora.Demo.Desktop.Features.Packages.Models;
using Nexora.Demo.Desktop.Features.Packages.Services;

namespace Nexora.Demo.Desktop.Features.Packages.Views;

public partial class PackageManagementView : UserControl
{
    private readonly string _providerKey;
    private DemoPackageCatalog _catalog = new();
    private readonly ObservableCollection<DemoPackageRow> _rows = new();

    public PackageManagementView(string providerKey)
    {
        _providerKey = providerKey is "user-manager" or "all" ? providerKey : "hotspot";
        InitializeComponent();
        PackagesDataGrid.ItemsSource = _rows;
        SearchTextBox.TextChanged += (_, _) => ApplyFilter();
        StatusFilterComboBox.SelectionChanged += (_, _) => ApplyFilter();
        PackagesDataGrid.SelectionChanged += (_, _) => UpdateSelectionActions();

        var isUserManager = _providerKey == "user-manager";
        var isAll = _providerKey == "all";
        ViewTitleTextBlock.Text = isAll ? "كتالوج الباقات" : isUserManager ? "باقات User Manager" : "باقات HotSpot";
        ViewSubtitleTextBlock.Text = isAll
            ? "تعريف تجاري موحد للباقة، مع ربط تقني مستقل لكل نظام. اختر جهة ربط عند الإضافة أو ربط تعريف موجود."
            : isUserManager
                ? "تعريف الباقة التجاري مشترك؛ ملفات المستخدم والقيود والمجموعات إعدادات خاصة بربط User Manager."
                : "تعريف الباقة التجاري مشترك؛ ملف HotSpot والخادم وحدود المشاركة إعدادات خاصة بهذا الربط.";
        ProviderColumn.Visibility = isAll ? Visibility.Visible : Visibility.Collapsed;
        PackageCountLabelTextBlock.Text = isAll ? "تعريفات الباقات" : "تعريفات مرتبطة بهذا النظام";
        ActiveBindingLabelTextBlock.Text = isAll ? "روابط نشطة" : "روابط نشطة لهذا النظام";
        PausedBindingLabelTextBlock.Text = isAll ? "روابط متوقفة" : "روابط متوقفة";
        RefreshPackages();
    }

    private void RefreshPackages()
    {
        StatusTextBlock.Text = "جار تحميل كتالوج الباقات...";
        try
        {
            _catalog = DemoPackageStore.Load();
            if (_catalog.Packages is null || _catalog.Bindings is null)
                throw new InvalidOperationException("كتالوج الباقات غير مكتمل.");

            var scopedBindings = _catalog.Bindings.Where(b => _providerKey == "all" || b.ProviderKey == _providerKey).ToArray();
            PackageCountTextBlock.Text = scopedBindings.Select(b => b.PackageId).Distinct(StringComparer.Ordinal).Count().ToString("N0");
            ActiveBindingCountTextBlock.Text = scopedBindings.Count(b => b.IsEnabled && !_catalog.Packages.Any(p => p.Id == b.PackageId && p.IsArchived)).ToString("N0");
            PausedBindingCountTextBlock.Text = scopedBindings.Count(b => !b.IsEnabled).ToString("N0");
            ApplyFilter();
        }
        catch (Exception ex)
        {
            _rows.Clear();
            EmptyStatePanel.Visibility = Visibility.Visible;
            EmptyStateDescriptionTextBlock.Text = "تعذر تحميل كتالوج الباقات. راجع بيانات الكتالوج قبل المتابعة.";
            StatusTextBlock.Text = "تعذر تحميل كتالوج الباقات.";
            UpdateSelectionActions();
            MessageBox.Show(Window.GetWindow(this), "تعذر تحميل كتالوج الباقات:\n" + ex.Message,
                "Nexora", MessageBoxButton.OK, MessageBoxImage.Error, MessageBoxResult.OK, MessageBoxOptions.RtlReading);
        }
    }

    private void ApplyFilter()
    {
        if (PackagesDataGrid is null) return;
        try
        {
            var query = SearchTextBox.Text?.Trim() ?? string.Empty;
            var filter = (StatusFilterComboBox.SelectedItem as ComboBoxItem)?.Tag?.ToString() ?? "all";
            var packageMap = _catalog.Packages.ToDictionary(p => p.Id, StringComparer.Ordinal);

            var rows = _catalog.Bindings
                .Where(b => (_providerKey == "all" || b.ProviderKey == _providerKey) && packageMap.ContainsKey(b.PackageId))
                .Select(b => new DemoPackageRow(packageMap[b.PackageId], b))
                .Where(row => filter switch
                {
                    "active" => row.Binding.IsEnabled && !row.Package.IsArchived,
                    "paused" => !row.Binding.IsEnabled,
                    "archived" => row.Package.IsArchived,
                    _ => true
                })
                .Where(row => query.Length == 0 ||
                    row.Name.Contains(query, StringComparison.CurrentCultureIgnoreCase) ||
                    row.TechnicalTargetDisplay.Contains(query, StringComparison.CurrentCultureIgnoreCase))
                .OrderBy(row => row.Name, StringComparer.CurrentCulture)
                .ToList();

            _rows.Clear();
            foreach (var row in rows) _rows.Add(row);
            EmptyStatePanel.Visibility = _rows.Count == 0 ? Visibility.Visible : Visibility.Collapsed;
            EmptyStateDescriptionTextBlock.Text = query.Length > 0
                ? "لا توجد نتيجة لهذا البحث. امسح عبارة البحث أو غيّر حالة العرض."
                : "لا توجد باقات في هذا النظام بعد. أنشئ تعريفًا جديدًا أو اربط تعريفًا موجودًا.";
            StatusTextBlock.Text = $"تم عرض {_rows.Count:N0} ربط باقة ضمن الفلاتر الحالية.";
            UpdateSelectionActions();
        }
        catch (Exception ex)
        {
            _rows.Clear();
            EmptyStatePanel.Visibility = Visibility.Visible;
            EmptyStateDescriptionTextBlock.Text = "تعذّر عرض الباقات بسبب مشكلة في بيانات الكتالوج.";
            StatusTextBlock.Text = "تعذّر تطبيق البحث أو التصفية: " + ex.Message;
            UpdateSelectionActions();
        }
    }

    private void UpdateSelectionActions()
    {
        var row = PackagesDataGrid?.SelectedItem as DemoPackageRow;
        EditSelectedButton.IsEnabled = row is not null && !row.Package.IsArchived;
        ToggleBindingButton.IsEnabled = row is not null && !row.Package.IsArchived;
        if (row is not null)
            ToggleBindingButton.Content = row.Binding.IsEnabled ? "إيقاف الربط" : "إعادة تفعيل الربط";
    }

    private void AddPackageButton_Click(object sender, RoutedEventArgs e)
    {
        var provider = ChooseProvider("أين تريد إتاحة هذه الباقة أولًا؟");
        if (provider is not null) OpenEditor(null, null, false, provider);
    }

    private void BindExistingPackageButton_Click(object sender, RoutedEventArgs e)
    {
        var provider = ChooseProvider("اختر النظام الذي تريد ربط تعريف الباقة به:");
        if (provider is not null) OpenEditor(null, null, true, provider);
    }

    private void EditSelectedButton_Click(object sender, RoutedEventArgs e)
    {
        if (PackagesDataGrid.SelectedItem is not DemoPackageRow row)
        {
            MessageBox.Show(Window.GetWindow(this), "اختر باقة أولًا.", "Nexora", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }
        OpenEditor(row.Package.Copy(), row.Binding.Copy(), false, row.Binding.ProviderKey);
    }

    private void PackagesDataGrid_MouseDoubleClick(object sender, System.Windows.Input.MouseButtonEventArgs e)
    {
        if (PackagesDataGrid.SelectedItem is DemoPackageRow row && !row.Package.IsArchived)
            OpenEditor(row.Package.Copy(), row.Binding.Copy(), false, row.Binding.ProviderKey);
    }

    private void OpenEditor(DemoServicePackage? package, DemoPackageBinding? binding, bool bindExisting, string providerKey)
    {
        try
        {
            var editor = new PackageEditorWindow(providerKey, package, binding, bindExisting)
            {
                Owner = Window.GetWindow(this)
            };
            if (editor.ShowDialog() == true)
            {
                RefreshPackages();
                StatusTextBlock.Text = "تم حفظ تعريف الباقة أو تحديث ربطها.";
            }
        }
        catch (Exception ex)
        {
            MessageBox.Show(Window.GetWindow(this), "تعذر فتح شاشة الباقة:\n" + ex.Message,
                "Nexora", MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private void ToggleBindingButton_Click(object sender, RoutedEventArgs e)
    {
        if (PackagesDataGrid.SelectedItem is not DemoPackageRow row) return;
        var enable = !row.Binding.IsEnabled;
        var action = enable ? "إعادة تفعيل" : "إيقاف";
        var answer = MessageBox.Show(Window.GetWindow(this),
            $"هل تريد {action} ربط الباقة «{row.Package.Name}» في هذا النظام؟\nتعريف الباقة التجاري سيبقى محفوظًا، ولن يتغير ربطها في النظام الآخر.",
            "تأكيد الإجراء", MessageBoxButton.YesNo, MessageBoxImage.Question, MessageBoxResult.No, MessageBoxOptions.RtlReading);
        if (answer != MessageBoxResult.Yes) return;

        try
        {
            var fresh = DemoPackageStore.Load();
            var target = fresh.Bindings.FirstOrDefault(b => b.Id == row.Binding.Id && b.ProviderKey == row.Binding.ProviderKey);
            if (target is null) throw new InvalidOperationException("لم يعد ربط الباقة موجودًا في كتالوج الباقات.");
            target.IsEnabled = enable;
            target.UpdatedAt = DateTimeOffset.Now;
            DemoPackageStore.Save(fresh);
            RefreshPackages();
            StatusTextBlock.Text = enable ? "تمت إعادة تفعيل ربط الباقة." : "تم إيقاف ربط الباقة في هذا النظام.";
        }
        catch (Exception ex)
        {
            MessageBox.Show(Window.GetWindow(this), "تعذر حفظ حالة الربط:\n" + ex.Message,
                "Nexora", MessageBoxButton.OK, MessageBoxImage.Error);
        }
    }

    private string? ChooseProvider(string prompt)
    {
        if (_providerKey != "all") return _providerKey;

        var dialog = new Window
        {
            Title = "اختيار جهة الربط",
            Width = 440,
            Height = 230,
            MinWidth = 400,
            MinHeight = 210,
            ResizeMode = ResizeMode.NoResize,
            WindowStartupLocation = WindowStartupLocation.CenterOwner,
            Owner = Window.GetWindow(this),
            FlowDirection = FlowDirection.RightToLeft,
            Background = System.Windows.Media.Brushes.White
        };
        var root = new StackPanel { Margin = new Thickness(22) };
        root.Children.Add(new TextBlock { Text = prompt, FontSize = 16, FontWeight = FontWeights.SemiBold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 0, 0, 14) });
        var buttons = new UniformGrid { Columns = 2 };
        var hotspot = new Button { Content = "HotSpot", Height = 42, Margin = new Thickness(0, 0, 6, 0), Background = (System.Windows.Media.Brush)Application.Current.FindResource("PrimaryLightBrush"), Foreground = (System.Windows.Media.Brush)Application.Current.FindResource("PrimaryBrush") };
        var userManager = new Button { Content = "User Manager", Height = 42, Margin = new Thickness(6, 0, 0, 0), Background = (System.Windows.Media.Brush)Application.Current.FindResource("PrimaryBrush"), Foreground = System.Windows.Media.Brushes.White };
        hotspot.Click += (_, _) => { dialog.Tag = "hotspot"; dialog.DialogResult = true; };
        userManager.Click += (_, _) => { dialog.Tag = "user-manager"; dialog.DialogResult = true; };
        buttons.Children.Add(hotspot);
        buttons.Children.Add(userManager);
        root.Children.Add(buttons);
        dialog.Content = root;
        return dialog.ShowDialog() == true ? dialog.Tag?.ToString() : null;
    }

    private void RefreshButton_Click(object sender, RoutedEventArgs e) => RefreshPackages();
}